// EDIT THIS LINE to restrict the bot. Empty array means anyone who finds the bot can use it.
const ALLOWED_CHAT_IDS = ['8784636815'];

const first = $input.first();
const msg = (first.json.message) || {};
const chat = msg.chat || {};
const chatId = String(chat.id || '');
const firstName = chat.first_name || 'there';
const text = String(msg.text || msg.caption || '').trim();
const hasVoice = Boolean(msg.voice || msg.audio);
const doc = msg.document || null;

const allowed = ALLOWED_CHAT_IDS.length === 0 || ALLOWED_CHAT_IDS.indexOf(chatId) !== -1;

let kind = 'text';
let command = '';
let arg = '';

if (hasVoice) {
  kind = 'voice';
} else if (doc) {
  kind = 'document';
} else if (text.indexOf('/') === 0) {
  kind = 'command';
  const parts = text.slice(1).split(/\s+/);
  command = String(parts[0] || '').toLowerCase().split('@')[0];
  arg = String(parts[1] || '').toLowerCase();
} else if (text.length === 0) {
  kind = 'other';
}

// Airtable formulas are built once here so every branch reuses the same escaped chat id.
const safeChat = chatId.replace(/'/g, '');
const formulaAttempts = "{chat_id}='" + safeChat + "'";
const formulaSessionOpen = "AND({chat_id}='" + safeChat + "',{status}='open')";
const formulaQuestionsActive = '{active}=1';
const formulaProfile = "{chat_id}='" + safeChat + "'";

// The voice note or CV arrives as binary on the trigger item. Returning a fresh json
// object would drop it, so it is carried through explicitly.
return [{
  json: {
    chat_id: chatId,
    first_name: firstName,
    text: text,
    kind: kind,
    command: command,
    arg: arg,
    allowed: allowed,
    doc_name: doc ? String(doc.file_name || '') : '',
    doc_mime: doc ? String(doc.mime_type || '') : '',
    formula_attempts: formulaAttempts,
    formula_session_open: formulaSessionOpen,
    formula_questions_active: formulaQuestionsActive,
    formula_profile: formulaProfile
  },
  binary: first.binary
}];

// Chooses the next question: weighted toward weak topics, skipping anything asked recently.
const n = $('Normalise message').first().json;
const TOPICS = ['behavioural', 'motivation', 'technical', 'company-fit', 'competency', 'case'];

function flat(items) {
  return items.map(function (it) {
    const f = it.json.fields || it.json;
    const out = {};
    for (const k in f) { out[k] = f[k]; }
    out._id = it.json.id || f.id;
    return out;
  });
}

const questions = flat($('Load question bank').all()).filter(function (q) { return q.question_id && q.text; });

let attempts = [];
try { attempts = flat($('Load my attempts').all()).filter(function (a) { return a.question_id; }); } catch (e) { attempts = []; }

let sessions = [];
try { sessions = flat($('Load open session').all()).filter(function (s) { return s.question_id; }); } catch (e) { sessions = []; }

const openSession = sessions.length > 0 ? sessions[0] : null;
const skipping = n.command === 'skip';
const now = Date.now();

if (questions.length === 0) {
  return [{ json: { found: false, chat_id: n.chat_id, reply: 'The question bank is empty. Add some rows to the questions table in Airtable first.' } }];
}

// Work out which topic the user asked for, if any.
const arg = String(n.arg || '');
let wantedTopics = TOPICS.slice();
let drillingWeak = false;

if (arg === 'weak') {
  drillingWeak = true;
} else if (arg.length > 0) {
  if (TOPICS.indexOf(arg) === -1) {
    return [{
      json: {
        found: false,
        chat_id: n.chat_id,
        reply: 'I do not know the topic "' + arg + '".\n\nTry one of these:\n' + TOPICS.map(function (t) { return '/practice ' + t; }).join('\n') + '\n\nOr just /practice for a mix, or /practice weak to drill your weakest topics.'
      }
    }];
  }
  wantedTopics = [arg];
}

// Average score per topic over the last 14 days, used for weighting.
const cutoff = now - 14 * 24 * 60 * 60 * 1000;
const recentAttempts = attempts.filter(function (a) {
  const t = Date.parse(a.created_at || '');
  return !isNaN(t) && t >= cutoff;
});

const byTopic = {};
recentAttempts.forEach(function (a) {
  const t = a.topic || 'unknown';
  if (!byTopic[t]) { byTopic[t] = { sum: 0, count: 0 }; }
  byTopic[t].sum += Number(a.score || 0);
  byTopic[t].count += 1;
});

if (drillingWeak) {
  const scored = TOPICS.filter(function (t) { return byTopic[t] && byTopic[t].count > 0; });
  if (scored.length === 0) {
    return [{ json: { found: false, chat_id: n.chat_id, reply: 'Not enough attempts yet to know your weak topics. Answer a few questions with /practice first.' } }];
  }
  scored.sort(function (a, b) { return (byTopic[a].sum / byTopic[a].count) - (byTopic[b].sum / byTopic[b].count); });
  wantedTopics = scored.slice(0, 3);
}

// Questions answered in the last 5 attempts are excluded so the same one does not come straight back.
const sortedAttempts = attempts.slice().sort(function (a, b) { return Date.parse(b.created_at || 0) - Date.parse(a.created_at || 0); });
const recentIds = sortedAttempts.slice(0, 5).map(function (a) { return a.question_id; });

// Anything with a due date in the past is owed a repeat.
const dueIds = {};
attempts.forEach(function (a) {
  const d = Date.parse(a.due_at || '');
  if (!isNaN(d) && d <= now) { dueIds[a.question_id] = true; }
});

let pool = questions.filter(function (q) { return wantedTopics.indexOf(q.topic) !== -1; });
if (pool.length === 0) { pool = questions.slice(); }

let fresh = pool.filter(function (q) { return recentIds.indexOf(q.question_id) === -1; });
if (skipping && openSession) {
  fresh = fresh.filter(function (q) { return q.question_id !== openSession.question_id; });
}
if (fresh.length === 0) { fresh = pool.slice(); }

// Due questions win outright; otherwise weight by how weak the topic is.
const dueFirst = fresh.filter(function (q) { return dueIds[q.question_id]; });
const candidates = dueFirst.length > 0 ? dueFirst : fresh;

const weighted = candidates.map(function (q) {
  const stat = byTopic[q.topic];
  const avg = stat && stat.count > 0 ? stat.sum / stat.count : 2.5;
  return { q: q, weight: (5 - avg) + Math.random() };
});
weighted.sort(function (a, b) { return b.weight - a.weight; });

const chosen = weighted[0].q;
const isDue = Boolean(dueIds[chosen.question_id]);

let lead = 'Here is your question';
if (drillingWeak) { lead = 'Drilling your weak topics'; }
else if (skipping) { lead = 'New question'; }
else if (isDue) { lead = 'This one came back round'; }

const reply = lead + ' (' + chosen.topic + ', difficulty ' + (chosen.difficulty || 2) + ')\n\n' + chosen.text + '\n\nAnswer by text or voice note. /hint if you are stuck, /skip for a different one.';

return [{
  json: {
    found: true,
    chat_id: n.chat_id,
    question_id: chosen.question_id,
    topic: chosen.topic,
    question_text: chosen.text,
    difficulty: chosen.difficulty || 2,
    reply: reply,
    started_at: new Date().toISOString()
  }
}];

// Serves both /weak and /stats from one read of the attempts table.
const n = $('Normalise message').first().json;

const rows = $input.all().map(function (it) {
  const f = it.json.fields || it.json;
  return { topic: f.topic, score: Number(f.score), created_at: f.created_at, question_id: f.question_id };
}).filter(function (r) { return r.topic && !isNaN(r.score) && r.created_at; });

if (rows.length === 0) {
  return [{ json: { chat_id: n.chat_id, reply: 'Not enough attempts yet. Send /practice and answer a few questions first.' } }];
}

const now = Date.now();
const cutoff = now - 14 * 24 * 60 * 60 * 1000;
const recent = rows.filter(function (r) { return Date.parse(r.created_at) >= cutoff; });

const byTopic = {};
recent.forEach(function (r) {
  if (!byTopic[r.topic]) { byTopic[r.topic] = { sum: 0, count: 0 }; }
  byTopic[r.topic].sum += r.score;
  byTopic[r.topic].count += 1;
});

const topics = [];
for (const t in byTopic) { topics.push(t); }

let reply = '';

if (n.command === 'weak') {
  if (topics.length === 0) {
    reply = 'Nothing in the last 14 days. Send /practice to start building a picture.';
  } else {
    topics.sort(function (a, b) { return (byTopic[a].sum / byTopic[a].count) - (byTopic[b].sum / byTopic[b].count); });
    const worst = topics.slice(0, 3);
    reply = 'Your weakest topics over the last 14 days:\n\n' + worst.map(function (t, i) {
      const avg = byTopic[t].sum / byTopic[t].count;
      return (i + 1) + '. ' + t + ' - ' + (Math.round(avg * 10) / 10) + '/5 over ' + byTopic[t].count + ' answer' + (byTopic[t].count === 1 ? '' : 's');
    }).join('\n') + '\n\nSend /practice weak to drill these.';
  }
} else {
  // Streak: count back from today over distinct days with at least one attempt.
  const days = {};
  rows.forEach(function (r) { days[new Date(Date.parse(r.created_at)).toISOString().slice(0, 10)] = true; });
  let streak = 0;
  let cursor = new Date();
  for (let i = 0; i < 365; i++) {
    const key = cursor.toISOString().slice(0, 10);
    if (days[key]) { streak += 1; }
    else if (i > 0) { break; }
    cursor = new Date(cursor.getTime() - 24 * 60 * 60 * 1000);
  }

  const total = rows.length;
  const overall = rows.reduce(function (s, r) { return s + r.score; }, 0) / total;

  const allTopics = [];
  const byTopicAll = {};
  rows.forEach(function (r) {
    if (!byTopicAll[r.topic]) { byTopicAll[r.topic] = { sum: 0, count: 0 }; allTopics.push(r.topic); }
    byTopicAll[r.topic].sum += r.score;
    byTopicAll[r.topic].count += 1;
  });
  allTopics.sort(function (a, b) { return (byTopicAll[b].sum / byTopicAll[b].count) - (byTopicAll[a].sum / byTopicAll[a].count); });

  reply = 'Your stats\n\nAnswers graded: ' + total + '\nAverage score: ' + (Math.round(overall * 10) / 10) + '/5\nCurrent streak: ' + streak + ' day' + (streak === 1 ? '' : 's') + '\n\nBy topic:\n' + allTopics.map(function (t) {
    const avg = byTopicAll[t].sum / byTopicAll[t].count;
    return '- ' + t + ': ' + (Math.round(avg * 10) / 10) + '/5 (' + byTopicAll[t].count + ')';
  }).join('\n');
}

return [{ json: { chat_id: n.chat_id, reply: reply } }];

// A hint names one checklist point without giving the whole rubric away.
const n = $('Normalise message').first().json;

let sessions = [];
try {
  sessions = $('Load session for hint').all().map(function (it) { return it.json.fields || it.json; }).filter(function (s) { return s.question_id; });
} catch (e) { sessions = []; }

if (sessions.length === 0) {
  return [{ json: { has_session: false, chat_id: n.chat_id, reply: 'You have no question open. Send /practice to get one.' } }];
}

const session = sessions[0];
const hintsUsed = Number(session.hints_used || 0);

const questions = $input.all().map(function (it) { return it.json.fields || it.json; }).filter(function (q) { return q.question_id; });

if (questions.length === 0) {
  return [{ json: { has_session: false, chat_id: n.chat_id, reply: 'I could not find that question any more. Send /practice for a new one.' } }];
}

let keyPoints = [];
try {
  const kp = questions[0].key_points;
  keyPoints = typeof kp === 'string' ? JSON.parse(kp) : (kp || []);
} catch (e) { keyPoints = []; }

if (keyPoints.length === 0) {
  return [{ json: { has_session: false, chat_id: n.chat_id, reply: 'No hints available for this one. Answer it as best you can.' } }];
}

if (hintsUsed >= keyPoints.length) {
  return [{ json: { has_session: false, chat_id: n.chat_id, reply: 'You have had every hint for this question. Give it a go, or /skip.' } }];
}

const point = keyPoints[hintsUsed];
const nextHints = hintsUsed + 1;

return [{
  json: {
    has_session: true,
    chat_id: n.chat_id,
    question_id: session.question_id,
    hints_used: nextHints,
    started_at: session.started_at || new Date().toISOString(),
    reply: 'Hint ' + nextHints + ' of ' + keyPoints.length + ':\n\nMake sure your answer does this - ' + point + '\n\nEach hint costs 0.5 off the score.'
  }
}];

// Builds the feedback message and splits it if it would exceed Telegram's 4096 character limit.
const g = $('Grade the answer').first().json;
const n = $('Normalise message').first().json;

const lines = [];
lines.push('Score: ' + g.score + '/5   (' + g.hits + ' of ' + g.total + ' key points covered)');
lines.push('');
lines.push('What you covered:');
lines.push(g.met_block || '-');
lines.push('');
lines.push('What you missed:');
lines.push(g.missed_block || '-');

if (g.feedback) {
  lines.push('');
  lines.push(g.feedback);
}

if (Number(g.hint_penalty) > 0) {
  lines.push('');
  lines.push('(-' + g.hint_penalty + ' for hints used)');
}

if (g.due_at) {
  lines.push('');
  lines.push('This one will come back round for another go.');
}

lines.push('');
lines.push('/practice for the next question, /weak to drill your weak spots, /stats for your progress.');

const full = lines.join('\n');

const LIMIT = 3900;
const chunks = [];
let rest = full;

while (rest.length > LIMIT) {
  let cut = rest.lastIndexOf('\n', LIMIT);
  if (cut < LIMIT / 2) { cut = LIMIT; }
  chunks.push(rest.slice(0, cut));
  rest = rest.slice(cut).replace(/^\n+/, '');
}
if (rest.length > 0) { chunks.push(rest); }

return chunks.map(function (c) {
  return { json: { chat_id: n.chat_id, reply: c } };
});

