// Telegram names voice notes file_N.oga. Groq accepts the ogg container but rejects the
// .oga extension by name, so the file is renamed before upload. Same bytes, same format.
const items = $input.all();

return items.map(function (item) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'voice.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
  return item;
});
